        return -1 if v < -1 else (1 if v > 1 else v)

    def first_present(d, keys):
        if not isinstance(d, dict):
            return None
        for k in keys:
            if k in d:
                return d.get(k)
        return None

    def as_pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            a, b = v[0], v[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
